import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r'''
.version 7.8
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 smem_base[];
// ---------------------------------------------------------------------
// Cooperative tiled 3D convolution kernel.
// Each CTA computes an 8x8x8 output tile for one (batch, out_channel),
// staging the required input halo tile (all input channels of the
// corresponding group) plus the output channel's weights into shared
// memory. 256 threads, each thread computes 2 outputs.
// ---------------------------------------------------------------------
.visible .entry conv3d_tiled(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 inC,
    .param .s32 outC,
    .param .s32 inD,
    .param .s32 inH,
    .param .s32 inW,
    .param .s32 outD,
    .param .s32 outH,
    .param .s32 outW,
    .param .s32 ksize,
    .param .s32 stride_p,
    .param .s32 pad_p,
    .param .s32 dil_p,
    .param .s32 groups_p,
    .param .s32 has_bias,
    .param .s32 tile_hd,
    .param .s32 tile_hh,
    .param .s32 tile_hw,
    .param .s32 ntw,
    .param .s32 nth
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<96>;
    .reg .b64 %rd<8>;
    .reg .f32 %f<4>;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [wt_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.s32 %r68, [inC];
    ld.param.s32 %r69, [outC];
    ld.param.s32 %r70, [inD];
    ld.param.s32 %r71, [inH];
    ld.param.s32 %r72, [inW];
    ld.param.s32 %r73, [outD];
    ld.param.s32 %r74, [outH];
    ld.param.s32 %r75, [outW];
    ld.param.s32 %r76, [ksize];
    ld.param.s32 %r77, [stride_p];
    ld.param.s32 %r78, [pad_p];
    ld.param.s32 %r79, [dil_p];
    ld.param.s32 %r80, [groups_p];
    ld.param.s32 %r81, [has_bias];
    ld.param.s32 %r82, [tile_hd];
    ld.param.s32 %r83, [tile_hh];
    ld.param.s32 %r84, [tile_hw];
    ld.param.s32 %r85, [ntw];
    ld.param.s32 %r86, [nth];
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ctaid.y;
    // decode (n, oc) from ctaid.y
    rem.s32 %r4, %r2, %r69;        // oc
    div.s32 %r3, %r2, %r69;        // n
    // decode tile coords (td, th, tw) from ctaid.x
    rem.s32 %r5, %r1, %r85;        // tw
    div.s32 %r6, %r1, %r85;
    rem.s32 %r7, %r6, %r86;        // th
    div.s32 %r8, %r6, %r86;        // td
    shl.b32 %r9, %r8, 3;           // base od
    shl.b32 %r10, %r7, 3;          // base oh
    shl.b32 %r11, %r5, 3;          // base ow
    // base input coords of the halo tile
    mul.lo.s32 %r12, %r9, %r77;
    sub.s32 %r12, %r12, %r78;      // base in_d
    mul.lo.s32 %r13, %r10, %r77;
    sub.s32 %r13, %r13, %r78;      // base in_h
    mul.lo.s32 %r14, %r11, %r77;
    sub.s32 %r14, %r14, %r78;      // base in_w
    div.s32 %r15, %r68, %r80;      // cpg = inC / groups
    div.s32 %r16, %r69, %r80;      // outC / groups
    div.s32 %r17, %r4, %r16;       // group of this oc
    mul.lo.s32 %r18, %r17, %r15;   // c0 = first input channel
    mul.lo.s32 %r19, %r76, %r76;   // k^2
    mul.lo.s32 %r20, %r19, %r76;   // k^3
    mul.lo.s32 %r21, %r15, %r20;   // wtot = cpg * k^3
    mul.lo.s32 %r22, %r82, %r83;   // HD*HH
    mul.lo.s32 %r23, %r22, %r84;   // HD*HH*HW
    mul.lo.s32 %r24, %r15, %r23;   // itot = cpg * HD*HH*HW
    mul.lo.s32 %r25, %r71, %r72;   // inH*inW
    mul.lo.s32 %r67, %r74, %r75;   // outH*outW
    mov.u64 %rd4, smem_base;
    // ---------------- stage weights into smem (after input tile) ------
    mov.s32 %r27, %r0;
LT_WSTAGE:
    setp.ge.s32 %p0, %r27, %r21;
    @%p0 bra LT_WSTAGE_DONE;
    mad.lo.s32 %r28, %r4, %r21, %r27;   // oc*wtot + idx
    cvt.s64.s32 %rd5, %r28;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd1, %rd5;
    ld.global.f32 %f1, [%rd5];
    add.s32 %r29, %r24, %r27;           // smem weight idx = itot + idx
    cvt.s64.s32 %rd6, %r29;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd6, %rd4, %rd6;
    st.shared.f32 [%rd6], %f1;
    add.s32 %r27, %r27, 256;
    bra LT_WSTAGE;
LT_WSTAGE_DONE:
    // ---------------- stage input halo tile into smem ----------------
    mov.s32 %r27, %r0;
LT_ISTAGE:
    setp.ge.s32 %p0, %r27, %r24;
    @%p0 bra LT_ISTAGE_DONE;
    rem.s32 %r28, %r27, %r84;      // x
    div.s32 %r29, %r27, %r84;
    rem.s32 %r30, %r29, %r83;      // y
    div.s32 %r31, %r29, %r83;
    rem.s32 %r32, %r31, %r82;      // z
    div.s32 %r33, %r31, %r82;      // c (within group)
    add.s32 %r34, %r12, %r32;      // gz
    add.s32 %r35, %r13, %r30;      // gy
    add.s32 %r36, %r14, %r28;      // gx
    mov.f32 %f1, 0f00000000;
    setp.lt.s32 %p1, %r34, 0;
    @%p1 bra LT_ISTORE;
    setp.ge.s32 %p1, %r34, %r70;
    @%p1 bra LT_ISTORE;
    setp.lt.s32 %p1, %r35, 0;
    @%p1 bra LT_ISTORE;
    setp.ge.s32 %p1, %r35, %r71;
    @%p1 bra LT_ISTORE;
    setp.lt.s32 %p1, %r36, 0;
    @%p1 bra LT_ISTORE;
    setp.ge.s32 %p1, %r36, %r72;
    @%p1 bra LT_ISTORE;
    add.s32 %r37, %r18, %r33;                 // c0 + c
    mad.lo.s32 %r37, %r3, %r68, %r37;         // n*inC + c0 + c
    mad.lo.s32 %r37, %r37, %r70, %r34;        // *inD + gz
    mad.lo.s32 %r38, %r35, %r72, %r36;        // gy*inW + gx
    mad.lo.s32 %r37, %r37, %r25, %r38;        // *(inH*inW) + ...
    cvt.s64.s32 %rd5, %r37;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd0, %rd5;
    ld.global.f32 %f1, [%rd5];
LT_ISTORE:
    cvt.s64.s32 %rd6, %r27;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd6, %rd4, %rd6;
    st.shared.f32 [%rd6], %f1;
    add.s32 %r27, %r27, 256;
    bra LT_ISTAGE;
LT_ISTAGE_DONE:
    bar.sync 0;
    // ---------------- compute: 2 outputs per thread -------------------
    mov.s32 %r39, 0;
LT_ILOOP:
    setp.ge.s32 %p0, %r39, 2;
    @%p0 bra LT_IDONE;
    mad.lo.s32 %r27, %r39, 256, %r0;          // linear idx in tile
    and.b32 %r40, %r27, 7;                    // ow_l
    shr.u32 %r28, %r27, 3;
    and.b32 %r41, %r28, 7;                    // oh_l
    shr.u32 %r42, %r28, 3;                    // od_l
    add.s32 %r43, %r11, %r40;                 // ow
    add.s32 %r44, %r10, %r41;                 // oh
    add.s32 %r45, %r9, %r42;                  // od
    setp.lt.s32 %p1, %r43, %r75;
    setp.lt.s32 %p2, %r44, %r74;
    and.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r45, %r73;
    and.pred %p1, %p1, %p2;                   // p1 = output valid
    mul.lo.s32 %r46, %r42, %r77;              // od_l*stride
    mul.lo.s32 %r47, %r41, %r77;              // oh_l*stride
    mul.lo.s32 %r48, %r40, %r77;              // ow_l*stride
    mov.f32 %f0, 0f00000000;
    setp.eq.s32 %p2, %r81, 0;
    @%p2 bra LT_BIASDONE;
    cvt.s64.s32 %rd5, %r4;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd2, %rd5;
    ld.global.f32 %f0, [%rd5];
LT_BIASDONE:
    mov.s32 %r49, 0;                          // c
LT_CLOOP:
    setp.ge.s32 %p2, %r49, %r15;
    @%p2 bra LT_CDONE;
    mul.lo.s32 %r50, %r49, %r82;              // c*HD
    mul.lo.s32 %r51, %r49, %r20;              // c*k^3
    mov.s32 %r52, 0;                          // kd
LT_KDLOOP:
    setp.ge.s32 %p2, %r52, %r76;
    @%p2 bra LT_KDDONE;
    mad.lo.s32 %r53, %r52, %r79, %r46;        // z = kd*dil + od_l*s
    add.s32 %r54, %r50, %r53;                 // c*HD + z
    mul.lo.s32 %r54, %r54, %r83;              // (c*HD + z)*HH
    mad.lo.s32 %r55, %r52, %r19, %r51;        // c*k^3 + kd*k^2
    mov.s32 %r56, 0;                          // kh
LT_KHLOOP:
    setp.ge.s32 %p2, %r56, %r76;
    @%p2 bra LT_KHDONE;
    mad.lo.s32 %r57, %r56, %r79, %r47;        // y
    add.s32 %r58, %r54, %r57;
    mul.lo.s32 %r58, %r58, %r84;              // ((c*HD+z)*HH + y)*HW
    mad.lo.s32 %r59, %r56, %r76, %r55;        // + kh*k
    mov.s32 %r60, 0;                          // kw
LT_KWLOOP:
    setp.ge.s32 %p2, %r60, %r76;
    @%p2 bra LT_KWDONE;
    mad.lo.s32 %r62, %r60, %r79, %r48;        // x
    add.s32 %r63, %r58, %r62;                 // smem input idx
    add.s32 %r64, %r59, %r60;                 // weight idx
    add.s32 %r64, %r64, %r24;                 // + itot
    cvt.s64.s32 %rd5, %r63;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd4, %rd5;
    ld.shared.f32 %f1, [%rd5];
    cvt.s64.s32 %rd6, %r64;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd6, %rd4, %rd6;
    ld.shared.f32 %f2, [%rd6];
    fma.rn.f32 %f0, %f1, %f2, %f0;
    add.s32 %r60, %r60, 1;
    bra LT_KWLOOP;
LT_KWDONE:
    add.s32 %r56, %r56, 1;
    bra LT_KHLOOP;
LT_KHDONE:
    add.s32 %r52, %r52, 1;
    bra LT_KDLOOP;
LT_KDDONE:
    add.s32 %r49, %r49, 1;
    bra LT_CLOOP;
LT_CDONE:
    mad.lo.s32 %r65, %r3, %r69, %r4;          // n*outC + oc
    mad.lo.s32 %r65, %r65, %r73, %r45;        // *outD + od
    mad.lo.s32 %r66, %r44, %r75, %r43;        // oh*outW + ow
    mad.lo.s32 %r65, %r65, %r67, %r66;        // *(outH*outW) + ...
    cvt.s64.s32 %rd5, %r65;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd3, %rd5;
    @%p1 st.global.f32 [%rd5], %f0;
    add.s32 %r39, %r39, 1;
    bra LT_ILOOP;
LT_IDONE:
    ret;
}
// ---------------------------------------------------------------------
// Original direct kernel, kept as fallback for shapes whose halo tile
// would exceed the dynamic shared-memory budget.
// ---------------------------------------------------------------------
.visible .entry conv3d_direct(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 total,
    .param .s32 inC,
    .param .s32 outC,
    .param .s32 inD,
    .param .s32 inH,
    .param .s32 inW,
    .param .s32 outD,
    .param .s32 outH,
    .param .s32 outW,
    .param .s32 ksize,
    .param .s32 stride_p,
    .param .s32 pad_p,
    .param .s32 dil_p,
    .param .s32 groups_p,
    .param .s32 has_bias
)
{
    .reg .pred %p<16>;
    .reg .b32 %r<96>;
    .reg .b64 %rd<12>;
    .reg .f32 %f<16>;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [wt_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.s32 %r2, [total];
    mov.u32 %r54, %ctaid.x;
    mov.u32 %r55, %ntid.x;
    mov.u32 %r56, %tid.x;
    mad.lo.s32 %r1, %r54, %r55, %r56;
    shl.b32 %r1, %r1, 2;
    setp.ge.s32 %p0, %r1, %r2;
    @%p0 ret;
    ld.param.s32 %r3, [inC];
    ld.param.s32 %r4, [outC];
    ld.param.s32 %r5, [inD];
    ld.param.s32 %r6, [inH];
    ld.param.s32 %r7, [inW];
    ld.param.s32 %r8, [outD];
    ld.param.s32 %r9, [outH];
    ld.param.s32 %r10, [outW];
    ld.param.s32 %r11, [ksize];
    ld.param.s32 %r12, [stride_p];
    ld.param.s32 %r13, [pad_p];
    ld.param.s32 %r14, [dil_p];
    ld.param.s32 %r15, [groups_p];
    ld.param.s32 %r16, [has_bias];
    mov.s32 %r58, 0;
L_OUT4:
    setp.ge.s32 %p8, %r58, 4;
    @%p8 ret;
    add.s32 %r59, %r1, %r58;
    setp.ge.s32 %p9, %r59, %r2;
    @%p9 bra L_OUT4_NEXT;
    rem.s32 %r17, %r59, %r10;
    div.s32 %r22, %r59, %r10;
    rem.s32 %r18, %r22, %r9;
    div.s32 %r22, %r22, %r9;
    rem.s32 %r19, %r22, %r8;
    div.s32 %r22, %r22, %r8;
    rem.s32 %r20, %r22, %r4;
    div.s32 %r21, %r22, %r4;
    mov.f32 %f0, 0f00000000;
    setp.eq.s32 %p1, %r16, 0;
    @%p1 bra L_BIAS_DONE;
    cvt.s64.s32 %rd4, %r20;
    shl.b64 %rd4, %rd4, 2;
    add.s64 %rd4, %rd2, %rd4;
    ld.global.f32 %f0, [%rd4];
L_BIAS_DONE:
    div.s32 %r23, %r3, %r15;
    div.s32 %r24, %r4, %r15;
    div.s32 %r25, %r20, %r24;
    mul.lo.s32 %r26, %r25, %r23;
    mul.lo.s32 %r27, %r6, %r7;
    mul.lo.s32 %r28, %r5, %r27;
    mul.lo.s32 %r29, %r3, %r28;
    mul.lo.s32 %r30, %r21, %r29;
    mul.lo.s32 %r31, %r11, %r11;
    mul.lo.s32 %r32, %r31, %r11;
    mul.lo.s32 %r33, %r23, %r32;
    mul.lo.s32 %r34, %r20, %r33;
    mul.lo.s32 %r35, %r19, %r12;
    sub.s32 %r35, %r35, %r13;
    mul.lo.s32 %r36, %r18, %r12;
    sub.s32 %r36, %r36, %r13;
    mul.lo.s32 %r37, %r17, %r12;
    sub.s32 %r37, %r37, %r13;
    mov.s32 %r38, 0;
L_IC:
    setp.ge.s32 %p2, %r38, %r23;
    @%p2 bra L_IC_DONE;
    add.s32 %r42, %r26, %r38;
    mad.lo.s32 %r43, %r42, %r28, %r30;
    mad.lo.s32 %r44, %r38, %r32, %r34;
    mov.s32 %r39, 0;
L_KD:
    setp.ge.s32 %p3, %r39, %r11;
    @%p3 bra L_KD_DONE;
    mad.lo.s32 %r45, %r39, %r14, %r35;
    setp.lt.s32 %p4, %r45, 0;
    @%p4 bra L_KD_NEXT;
    setp.ge.s32 %p5, %r45, %r5;
    @%p5 bra L_KD_NEXT;
    mad.lo.s32 %r46, %r45, %r27, %r43;
    mad.lo.s32 %r47, %r39, %r31, %r44;
    mov.s32 %r40, 0;
L_KH:
    setp.ge.s32 %p6, %r40, %r11;
    @%p6 bra L_KH_DONE;
    mad.lo.s32 %r48, %r40, %r14, %r36;
    setp.lt.s32 %p4, %r48, 0;
    @%p4 bra L_KH_NEXT;
    setp.ge.s32 %p5, %r48, %r6;
    @%p5 bra L_KH_NEXT;
    mad.lo.s32 %r49, %r48, %r7, %r46;
    mad.lo.s32 %r50, %r40, %r11, %r47;
    mov.s32 %r41, 0;
L_KW:
    setp.ge.s32 %p7, %r41, %r11;
    @%p7 bra L_KW_DONE;
    mad.lo.s32 %r51, %r41, %r14, %r37;
    setp.lt.s32 %p4, %r51, 0;
    @%p4 bra L_KW_NEXT;
    setp.ge.s32 %p5, %r51, %r7;
    @%p5 bra L_KW_NEXT;
    add.s32 %r52, %r49, %r51;
    add.s32 %r53, %r50, %r41;
    cvt.s64.s32 %rd4, %r52;
    shl.b64 %rd4, %rd4, 2;
    add.s64 %rd4, %rd0, %rd4;
    ld.global.f32 %f1, [%rd4];
    cvt.s64.s32 %rd5, %r53;
    shl.b64 %rd5, %rd5, 2;
    add.s64 %rd5, %rd1, %rd5;
    ld.global.f32 %f2, [%rd5];
    fma.rn.f32 %f0, %f1, %f2, %f0;
L_KW_NEXT:
    add.s32 %r41, %r41, 1;
    bra L_KW;
L_KW_DONE:
L_KH_NEXT:
    add.s32 %r40, %r40, 1;
    bra L_KH;
L_KH_DONE:
L_KD_NEXT:
    add.s32 %r39, %r39, 1;
    bra L_KD;
L_KD_DONE:
    add.s32 %r38, %r38, 1;
    bra L_IC;
L_IC_DONE:
    cvt.s64.s32 %rd4, %r59;
    shl.b64 %rd4, %rd4, 2;
    add.s64 %rd4, %rd3, %rd4;
    st.global.f32 [%rd4], %f0;
L_OUT4_NEXT:
    add.s32 %r58, %r58, 1;
    bra L_OUT4;
    ret;
}
'''
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    module = _get_ptx_module()
    module.function('conv3d_tiled')
    module.function('conv3d_direct')
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv3d
        n, ic, d, h, w = x.shape
        oc = conv.out_channels
        k = conv.kernel_size[0]
        s = conv.stride[0]
        p = conv.padding[0]
        dil = conv.dilation[0]
        g = conv.groups
        od = (d + 2 * p - dil * (k - 1) - 1) // s + 1
        oh = (h + 2 * p - dil * (k - 1) - 1) // s + 1
        ow = (w + 2 * p - dil * (k - 1) - 1) // s + 1
        out = torch.empty((n, oc, od, oh, ow), dtype=x.dtype, device=x.device)
        total = n * oc * od * oh * ow
        if total == 0:
            return out
        weight = conv.weight
        if conv.bias is not None:
            bias_arg = conv.bias
            has_bias = 1
        else:
            bias_arg = weight
            has_bias = 0
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(x.device)
        # Tiled path: 8x8x8 output tile per CTA, input halo + weights in smem
        cpg = ic // g
        hd = 7 * s + dil * (k - 1) + 1
        hh = 7 * s + dil * (k - 1) + 1
        hw = 7 * s + dil * (k - 1) + 1
        smem_bytes = 4 * (cpg * hd * hh * hw + cpg * k * k * k)
        ntw = (ow + 7) // 8
        nth = (oh + 7) // 8
        ntd = (od + 7) // 8
        grid_x = ntd * nth * ntw
        grid_y = n * oc
